mapper.select:
SELECT u.id, u.fleet_id, u.employee_no, u.name FROM sys_user u
JOIN fleet f ON f.id=u.fleet_id AND f.enabled=1
WHERE u.role='DRIVER' AND u.enabled=1
AND u.fleet_id=#{fleetId}
ORDER BY u.id LIMIT #{limit} OFFSET #{offset}

mapper.sql:
o.captured_at>=#{start} AND o.captured_at<#{end} AND o.driver_id IS NOT NULL
AND o.fleet_id=#{fleetId}
AND o.driver_id=#{driverId}
